import sys
sys.setrecursionlimit(10000)
def comps(grid, val):
    R=len(grid);C=len(grid[0]);seen=[[False]*C for _ in range(R)];out=[]
    for r in range(R):
        for c in range(C):
            if grid[r][c]==val and not seen[r][c]:
                stack=[(r,c)];seen[r][c]=True;comp=[]
                while stack:
                    x,y=stack.pop();comp.append((x,y))
                    for dx,dy in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=x+dx,y+dy
                        if 0<=a<R and 0<=b<C and grid[a][b]==val and not seen[a][b]:
                            seen[a][b]=True;stack.append((a,b))
                out.append(comp)
    return out
